<script setup>
const props=defineProps({modelValue:{type:Array,default:()=>[]}});const emit=defineEmits(['update:modelValue']);
function update(index,value){const items=[...props.modelValue];items[index]=value;emit('update:modelValue',items);}
function remove(index){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index));}
function move(index,offset){const items=[...props.modelValue];[items[index],items[index+offset]]=[items[index+offset],items[index]];emit('update:modelValue',items);}
</script>
<template><section class="image-editor"><h3>剧集图片</h3><p>第一张作为主海报；后面可放官方追剧日历、其他海报等。</p><div v-for="(url,index) in modelValue" :key="index" class="image-row"><label>{{index===0?'主海报':'图片 '+(index+1)}}<input type="url" :value="url" @input="update(index,$event.target.value)" placeholder="https://…" :aria-label="index===0?'主海报图片链接':'图片 '+(index+1)+' 链接'"></label><div class="image-actions"><button type="button" :disabled="index===0" @click="move(index,-1)" :aria-label="'上移图片 '+(index+1)">上移</button><button type="button" :disabled="index===modelValue.length-1" @click="move(index,1)" :aria-label="'下移图片 '+(index+1)">下移</button><button type="button" @click="remove(index)" :aria-label="'删除图片 '+(index+1)">删除</button></div></div><button type="button" @click="emit('update:modelValue',[...modelValue,''])">＋ 添加图片链接</button></section></template>
<style scoped>.image-editor{margin:24px 0}.image-editor h3{font-size:17px;margin:0 0 8px}.image-editor p{font-size:12px;line-height:1.6;color:#7d857d}.image-row{margin:16px 0}.image-row label{display:flex;flex-direction:column;gap:6px;font-size:14px}.image-row input{width:100%;min-width:0;border:1px solid #d9ded7;border-radius:7px;padding:9px;box-sizing:border-box;font:inherit;background:white}.image-actions{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap;margin-top:8px}button{font:inherit;font-size:12px;border:1px solid #d9ded7;border-radius:7px;padding:7px 12px;background:white;color:#303b35;cursor:pointer}button:disabled{opacity:.35;cursor:default}</style>
